SELECT sub0.time AS "time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() AND "time" < now() + interval '4d' GROUP BY 1 ORDER BY 1 ASC LIMIT 5) sub0 ORDER BY 1 DESC LIMIT 3